def totals(csv_text):
    if not csv_text or csv_text.strip() == "":
        return ""

    import csv
    from decimal import Decimal

    # Split the input into lines
    lines = csv_text.splitlines()

    # Use csv.DictReader to parse the input
    reader = csv.DictReader(lines, delimiter=',', quotechar='"')

    # Dictionary to store total amounts per name
    totals = {}

    for row in reader:
        name = row.get('name')
        amount_str = row.get('amount')

        if name and amount_str:
            try:
                amount = Decimal(amount_str)
                totals[name] = totals.get(name, Decimal('0')) + amount
            except (ValueError, TypeError):
                continue

    # Format the output with two decimal places
    result = {}
    for name, total in totals.items():
        result[name] = f'{total:.2f}'

    return result

